import {report,stats} from './engine.js';import {CFG} from './data.js';
export function assessment(s){const r=report(s),f=s.flight;const configuration=(s.parts.some(x=>x.startsWith('chamber'))?8:0)+(f.outages===0?8:0)+(f.risk<=35?8:0)+(f.sent>=100&&f.lost<1e-6?8:0)+(f.integrity>=80?8:0);const values={repair:1,battery:.75,power:.65,align:1,essential:.6,wait:0,continue:0};const decisions=f.decisions.length?40*f.decisions.reduce((a,d)=>a+(values[d.id]??0),0)/f.decisions.length:40;const resources=(f.charge>=CFG.batteryWh*.15?10:10*Math.max(0,f.charge)/(CFG.batteryWh*.15))+10*Math.min(1,Math.max(0,stats(s).budget)/500);const raw=Math.round(configuration+decisions+resources);const score=r.kind==='failure'?Math.min(49,raw):r.kind==='partial'?Math.min(79,raw):raw;return {configuration,decisions:Math.round(decisions),resources:Math.round(resources),raw,score,kind:!r.arrived||score<50?'bankrupt':score<80?'extension':'nobel',limited:score!==raw};}
